const BATTLEGROUND_AB_LIKE_CPP: u32 = 3;
const XP_HOOK_DOUBLE_PLAYER_COUNTER: i64 = 0xE1D0;
const XP_HOOK_ZERO_PLAYER_COUNTER: i64 = 0xE1D1;
const XP_HOOK_MAX_PLAYER_COUNTER: i64 = 0xE1D2;
const XP_HOOK_GUARD_PLAYER_COUNTER: i64 = 0xE1D3;

static XP_HOOK_DOUBLE_CALLS: AtomicUsize = AtomicUsize::new(0);
static XP_HOOK_ZERO_CALLS: AtomicUsize = AtomicUsize::new(0);
static XP_HOOK_MAX_CALLS: AtomicUsize = AtomicUsize::new(0);
static XP_HOOK_GUARD_CALLS: AtomicUsize = AtomicUsize::new(0);

fn represented_test_give_player_xp_hook_like_cpp(
    context: wow_script::player::GivePlayerXpContextLikeCpp,
    amount: &mut u32,
) {
    match context.player_guid.counter() {
        XP_HOOK_DOUBLE_PLAYER_COUNTER => {
            assert_eq!(context.victim_guid.counter(), 0xE1D0);
            XP_HOOK_DOUBLE_CALLS.fetch_add(1, AtomicOrdering::SeqCst);
            *amount = amount.saturating_mul(2);
        }
        XP_HOOK_ZERO_PLAYER_COUNTER => {
            assert_eq!(context.victim_guid.counter(), 0xE1D1);
            XP_HOOK_ZERO_CALLS.fetch_add(1, AtomicOrdering::SeqCst);
            *amount = 0;
        }
        XP_HOOK_MAX_PLAYER_COUNTER => {
            assert_eq!(context.victim_guid.counter(), 0xE1D2);
            XP_HOOK_MAX_CALLS.fetch_add(1, AtomicOrdering::SeqCst);
        }
        XP_HOOK_GUARD_PLAYER_COUNTER => {
            XP_HOOK_GUARD_CALLS.fetch_add(1, AtomicOrdering::SeqCst);
        }
        _ => {}
    }
}

/// Exact propagated Map-tick time needed for a scheduled assistance call.
/// There is no scheduler margin after #371 because wall time cannot advance
/// the creature between scheduling and the explicit logical-clock step.
const ASSISTANCE_DELAY_ELAPSED_LIKE_CPP: Duration =
    Duration::from_millis(wow_movement::CREATURE_FAMILY_ASSISTANCE_DELAY_MS_LIKE_CPP as u64);

fn make_session() -> (
    WorldSession,
    flume::Sender<WorldPacket>,
    flume::Receiver<Vec<u8>>,
) {
    let (pkt_tx, pkt_rx) = flume::bounded(100);
    let (send_tx, send_rx) = flume::unbounded();

    let mut session = WorldSession::new(
        1,
        "TestAccount".into(),
        0,
        2,
        9, // account_expansion (raw from DB)
        54261,
        vec![0u8; 40],
        "esES".into(),
        pkt_rx,
        send_tx,
    );
    session.set_active_player_local_flags_like_cpp(
        PLAYER_LOCAL_FLAG_OVERRIDE_TRANSPORT_SERVER_TIME_LIKE_CPP,
    );

    (session, pkt_tx, send_rx)
}

#[test]
fn character_login_claim_allows_only_one_live_session_like_cpp() {
    let guid = ObjectGuid::create_player(1, 0x7FFF_FF01);
    let (mut first, _, _) = make_session();
    let (mut second, _, _) = make_session();

    assert!(first.try_claim_character_login_like_cpp(guid));
    assert!(first.try_claim_character_login_like_cpp(guid));
    assert!(!second.try_claim_character_login_like_cpp(guid));

    first.release_character_login_claim_like_cpp();
    assert!(second.try_claim_character_login_like_cpp(guid));
    second.release_character_login_claim_like_cpp();
}

#[tokio::test]
async fn closed_instance_link_releases_character_login_claim_like_cpp() {
    let guid = ObjectGuid::create_player(1, 0x7FFF_FF02);
    let (mut first, _, _) = make_session();
    let (mut second, _, _) = make_session();

    assert!(first.try_claim_character_login_like_cpp(guid));
    first.set_player_loading(Some(guid));
    first.set_connect_to_key(Some(77));
    let (link_tx, link_rx) = tokio::sync::oneshot::channel();
    first.set_instance_link_rx(Some(link_rx));
    drop(link_tx);

    first.poll_instance_link().await;

    assert_eq!(first.player_loading(), None);
    assert_eq!(first.connect_to_key(), None);
    assert!(
        second.try_claim_character_login_like_cpp(guid),
        "a failed instance handoff must not strand the process-wide login claim"
    );
    second.release_character_login_claim_like_cpp();
}

#[test]
fn spell_acquisition_catalog_arc_is_shared_with_session() {
    let (mut session, _, _) = make_session();
    let catalog = Arc::new(
        SpellAcquisitionCatalogLikeCpp::from_effective_rows_like_cpp(
            std::iter::empty(),
            wow_data::EffectiveSpellAcquisitionRowsLikeCpp::default(),
            wow_data::SpellAcquisitionTableHashesLikeCpp::default(),
            Vec::new(),
        ),
    );

    session.set_spell_acquisition_catalog(Arc::clone(&catalog));

    assert!(Arc::ptr_eq(
        &catalog,
        session
            .spell_acquisition_catalog()
            .expect("the process-wide catalog must be installed")
    ));
}

#[test]
fn player_interaction_data_has_one_exact_reset_and_match_owner_like_cpp() {
    let trainer_a = ObjectGuid::create_world_object(HighGuid::Creature, 0, 1, 0, 0, 100, 1);
    let trainer_b = ObjectGuid::create_world_object(HighGuid::Creature, 0, 1, 0, 0, 101, 1);
    let mut interaction = PlayerInteractionDataLikeCpp::default();

    assert!(interaction.source_guid.is_empty());
    assert_eq!(interaction.trainer_id, 0);
    assert!(!interaction.trainer_matches(trainer_a, 0));

    interaction.set_trainer(trainer_a, 10);
    assert!(interaction.trainer_matches(trainer_a, 10));
    assert!(!interaction.trainer_matches(trainer_b, 10));
    assert!(!interaction.trainer_matches(trainer_a, 11));

    interaction.set_trainer(trainer_a, u32::MAX);
    assert!(interaction.trainer_matches(trainer_a, -1));
    interaction.set_trainer(trainer_a, 0x8000_0000);
    assert!(interaction.trainer_matches(trainer_a, i32::MIN));

    interaction.set_source(trainer_b);
    assert_eq!(interaction.source_guid, trainer_b);
    assert_eq!(
        interaction.trainer_id, 0,
        "a generic C++ interaction replaces the complete prior trainer provenance"
    );
    assert!(
        !interaction.trainer_matches(trainer_b, 0),
        "a generic source with C++'s reset TrainerId=0 is not an active trainer window"
    );
    assert!(!interaction.reset_if_source(trainer_a));
    assert_eq!(interaction.source_guid, trainer_b);
    assert!(interaction.reset_if_source(trainer_b));
    assert_eq!(interaction, PlayerInteractionDataLikeCpp::default());
}

#[test]
fn player_menu_state_does_not_survive_character_lifetime_like_cpp() {
    let (mut session, _, _) = make_session();
    let first_player = ObjectGuid::create_player(1, 70_001);
    let second_player = ObjectGuid::create_player(1, 70_002);
    let trainer = ObjectGuid::create_world_object(HighGuid::Creature, 0, 1, 0, 0, 100, 1);
    session.set_player_guid(Some(first_player));
    session.visible_auras.insert(0, test_visible_aura(0, 999));
    session.player_aura_authority_complete_like_cpp = true;
    assert!(session.set_complete_player_skill_records_like_cpp(
        HashMap::from([(
            95,
            RepresentedPlayerSkillLikeCpp {
                skill_id: 95,
                step: 0,
                value: 0,
                max: 0,
                profession_slot: -1,
                state: RepresentedPlayerSkillStateLikeCpp::Deleted,
            },
        )]),
        1,
    ));
    assert!(
        session
            .player_skill_non_durable_tombstones_like_cpp
            .contains(&95)
    );
    session.set_player_trainer_interaction_like_cpp(trainer, 77);
    session.record_spell_acquisition_post_commit_action_like_cpp(
        crate::spell_acquisition::SpellAcquisitionPostCommitActionLikeCpp::UpdateMountCapability {
            skill_id: u32::from(SKILL_RIDING_LIKE_CPP),
        },
    );
    session.gossip_options.push(GossipOptionInfo {
        gossip_option_id: 1,
        menu_id: 2,
        order_index: 3,
        option_npc: 4,
        action_menu_id: 5,
    });

    session.set_player_guid(Some(first_player));
    assert!(
        session.player_trainer_interaction_matches_like_cpp(trainer, 77),
        "reasserting the same Player identity must not reset its PlayerMenu"
    );
    assert_eq!(session.gossip_options.len(), 1);
    assert_eq!(
        session.visible_auras.get(&0).map(|aura| aura.spell_id),
        Some(999)
    );
    assert!(session.player_aura_authority_complete_like_cpp());
    assert!(
        session
            .player_skill_non_durable_tombstones_like_cpp
            .contains(&95),
        "reasserting the same Player identity retains its skill tombstones"
    );

    session.set_player_guid(None);

    assert!(session.player_interaction_source_guid_like_cpp().is_none());
    assert_eq!(session.player_interaction_trainer_id_like_cpp(), 0);
    assert!(session.gossip_options.is_empty());
    assert!(
        session.visible_auras.is_empty(),
        "active auras cannot cross a C++ Player lifetime"
    );
    assert!(
        !session.player_aura_authority_complete_like_cpp(),
        "the next Player must establish its own complete aura authority"
    );
    assert!(
        session
            .player_skill_non_durable_tombstones_like_cpp
            .is_empty(),
        "skill tombstones cannot cross a C++ Player lifetime"
    );
    assert!(
        session
            .represented_spell_acquisition_post_commit_actions_like_cpp()
            .is_empty(),
        "post-commit player intents cannot cross a character lifetime"
    );

    session.set_player_guid(Some(second_player));
    assert!(session.player_interaction_source_guid_like_cpp().is_none());
    assert!(session.gossip_options.is_empty());
    assert!(session.visible_auras.is_empty());
    assert!(!session.player_aura_authority_complete_like_cpp());
}

fn player_target_aura_spell_info_fixture_like_cpp(spell_id: i32, aura_types: &[i32]) -> SpellInfo {
    SpellInfo {
        spell_id,
        cast_time_ms: 0,
        cooldown_ms: 0,
        recovery_time_ms: 0,
        effect_type: wow_data::spell::spell_effect_types::SPELL_EFFECT_APPLY_AURA,
        effect_base_points: 0,
        effect_bonus_coefficient: 0.0,
        aura_type: aura_types.first().copied(),
        display_flags: 0,
        requires_spell_focus: 0,
        power_costs: Vec::new(),
        effects: aura_types
            .iter()
            .copied()
            .enumerate()
            .map(|(effect_index, effect_aura)| wow_data::SpellEffectInfo {
                effect_index: effect_index as u32,
                effect: wow_data::spell::spell_effect_types::SPELL_EFFECT_APPLY_AURA,
                effect_aura,
                ..Default::default()
            })
            .collect(),
    }
}

