#[test]
fn visibility_barrier_preserves_entire_durable_suffix_fifo_like_cpp() {
    let (session, _, _) = make_session();
    let creature_guid = test_creature_guid(1013);
    let victim_guid = ObjectGuid::create_player(1, 7007);
    {
        let mut durable = session
            .durable_creature_runtime_commands_like_cpp
            .lock()
            .unwrap();
        assert!(
            durable.publish_attack_start_like_cpp(CreatureAttackStartLikeCppCommand {
                attacker_guid: creature_guid,
                victim_guid,
                previous_victim_guid: None,
                map_id: 571,
                instance_id: 0,
                packet_already_broadcast: false,
            },)
        );
        for packet_bytes in [vec![0x37, 0x2C], vec![0x36, 0x2C]] {
            assert!(
                durable.publish_send_if_visible_like_cpp(SendIfVisibleLikeCppCommand {
                    queued_at: Instant::now(),
                    source_guid: creature_guid,
                    map_id: 571,
                    instance_id: 0,
                    packet_bytes,
                },)
            );
        }
        assert!(
            durable.publish_melee_damage_like_cpp(ApplyCreatureMeleeDamageLikeCppCommand {
                attacker_guid: creature_guid,
                victim_guid,
                map_id: 571,
                instance_id: 0,
                damage: 3,
                over_damage: -1,
                target_level: 80,
                victim_health_after: 97,
                victim_health_state_revision_after: 1,
            },)
        );
    }
    session
        .session_command_tx()
        .try_send(SessionCommand::RefreshVisibleWorldCreaturesLikeCpp(
            RefreshVisibleWorldCreaturesLikeCppCommand {
                map_id: 571,
                instance_id: 0,
            },
        ))
        .expect("refresh queued");

    let commands = session.drain_session_commands();
    assert_eq!(commands.len(), 5);
    assert!(matches!(
        &commands[0],
        SessionCommand::CreatureAttackStartLikeCpp(_)
    ));
    assert!(matches!(
        &commands[1],
        SessionCommand::RefreshVisibleWorldCreaturesLikeCpp(_)
    ));
    let SessionCommand::SendIfVisibleLikeCpp(start) = &commands[2] else {
        panic!("START must remain first in the deferred durable suffix");
    };
    let SessionCommand::SendIfVisibleLikeCpp(go) = &commands[3] else {
        panic!("GO must remain immediately behind START");
    };
    assert_eq!(start.packet_bytes, vec![0x37, 0x2C]);
    assert_eq!(go.packet_bytes, vec![0x36, 0x2C]);
    assert!(matches!(
        &commands[4],
        SessionCommand::ApplyCreatureMeleeDamageLikeCpp(_)
    ));
}

#[tokio::test]
async fn durable_creature_runtime_overflow_disconnects_desynchronized_session() {
    let (mut session, _, _) = make_session();
    let attacker_guid =
        ObjectGuid::create_world_object(HighGuid::Creature, 0, 1, 571, 0, 777, 1012);
    let victim_guid = ObjectGuid::create_player(1, 7006);
    session.state = SessionState::LoggedIn;
    session.set_player_guid(Some(victim_guid));
    let command = CreatureAttackStartLikeCppCommand {
        attacker_guid,
        victim_guid,
        previous_victim_guid: None,
        map_id: 571,
        instance_id: 0,
        packet_already_broadcast: false,
    };
    {
        let mut pending = session
            .durable_creature_runtime_commands_like_cpp
            .lock()
            .unwrap();
        for _ in 0..crate::session::mailbox::MAX_DURABLE_CREATURE_RUNTIME_COMMANDS_LIKE_CPP {
            assert!(pending.publish_attack_start_like_cpp(command.clone()));
        }
        assert!(!pending.publish_attack_start_like_cpp(command));
    }

    session
        .process_represented_session_commands_like_cpp()
        .await;

    assert!(session.is_disconnecting());
    assert!(
        session
            .durable_creature_runtime_commands_like_cpp
            .lock()
            .unwrap()
            .drain_like_cpp()
            .is_empty()
    );
}

/// Future global creature CREATE/DESTROY work must not use
/// `SendIfVisibleLikeCpp`: a not-yet-visible creature needs the session's
/// visibility pass to build CREATE bytes and update HaveAtClient.
#[tokio::test]
async fn refresh_visible_world_creatures_command_forces_creature_visibility_like_cpp() {
    let (mut session, _, send_rx) = make_session();
    let manager = shared_map_manager();
    let player_position = Position::new(10.0, 10.0, 0.0, 0.0);
    let creature_guid = test_creature_guid(90_010);
    let creature_position = Position::new(12.0, 10.0, 0.0, 0.0);
    let (grid_x, grid_y) =
        crate::map_manager::world_to_grid_coords(creature_position.x, creature_position.y);
    manager.write().unwrap().add_creature(
        571,
        0,
        grid_x,
        grid_y,
        crate::map_manager::WorldCreature::new(
            creature_guid,
            901,
            creature_position,
            100,
            80,
            1,
            2,
            0.0,
            1,
            35,
            0,
            0,
        ),
    );

    session.state = SessionState::LoggedIn;
    session.set_map_manager(manager);
    session.set_player_map_position_like_cpp(571, player_position);
    // Prove the command bypasses the 50-yard visibility throttle.
    session.last_visibility_pos = Some(player_position);

    session
        .session_command_tx()
        .try_send(SessionCommand::RefreshVisibleWorldCreaturesLikeCpp(
            RefreshVisibleWorldCreaturesLikeCppCommand {
                map_id: 571,
                instance_id: 0,
            },
        ))
        .expect("command queued");
    session
        .process_represented_session_commands_like_cpp()
        .await;

    assert!(
        session
            .client_visible_guids_like_cpp
            .contains(&creature_guid),
        "forced creature visibility must create the unseen creature"
    );
    let packet = send_rx
        .try_recv()
        .expect("creature CREATE visibility packet");
    let opcode = u16::from_le_bytes([packet[0], packet[1]]);
    assert_eq!(opcode, ServerOpcodes::UpdateObject as u16);
    assert!(send_rx.try_recv().is_err(), "no extra packets");
}

