fn register_test_creature(
    session: &mut WorldSession,
    manager: crate::map_manager::SharedMapManager,
    guid: ObjectGuid,
    hp: u32,
) {
    session.set_map_manager(manager);
    session.current_map_id = 0;
    if session.player_position_like_cpp().is_none() {
        session.set_player_map_position_like_cpp(0, Position::new(10.0, 10.0, 0.0, 0.0));
    }
    session.register_world_creature(
        0,
        Position::new(10.0, 10.0, 0.0, 0.0),
        test_creature_create_data(guid, 9001, hp),
        3,
        5,
        20.0,
        0,
        0,
        0,
        0,
        None,
        0,
        0,
        0,
        0,
        -1,
    );
    session
        .mutate_world_creature(guid, |creature| {
            // This test fixture represents a fully hydrated DB-backed
            // creature with no addon/template-addon auras.
            creature
                .creature
                .unit_mut()
                .subsystems_mut()
                .auras
                .set_spell_hit_aura_authority_inert_like_cpp(true);
            creature
                .creature
                .unit_mut()
                .subsystems_mut()
                .auras
                .set_spell_cast_log_aura_authority_inert_like_cpp(true);
            creature.seed_runtime_rng_like_cpp(0x5E11_117);
        })
        .expect("registered test creature must remain available");
}

/// Register a legacy creature the way production does: through a session
/// that already owns the canonical map manager.
///
/// `register_world_creature` reconciles the legacy and canonical loot and
/// health-state authorities while mirroring, which is what makes the two
/// entities one incarnation. Cast and melee paths that prove that identity
/// need this fixture rather than two independently constructed creatures.
fn register_test_creature_mirrored_like_cpp(
    session: &mut WorldSession,
    manager: crate::map_manager::SharedMapManager,
    canonical: &SharedCanonicalMapManager,
    guid: ObjectGuid,
    hp: u32,
) {
    session.set_canonical_map_manager(Arc::clone(canonical));
    register_test_creature(session, manager, guid, hp);
}

#[test]
fn creature_create_stats_uses_spawn_curmana_when_health_regen_disabled_like_cpp() {
    let (mut session, _, _) = make_session();
    session.set_creature_difficulty_store_like_cpp(Arc::new(
        wow_data::CreatureDifficultyStoreLikeCpp::from_records(
            [wow_data::CreatureDifficultyRecordLikeCpp {
                entry: 90_021,
                difficulty_id: 0,
                min_level: 5,
                max_level: 5,
                health_scaling_expansion: 0,
                health_modifier: 1.0,
                mana_modifier: 1.0,
                armor_modifier: 1.0,
                damage_modifier: 1.0,
                creature_difficulty_id: 0,
                type_flags: 0,
                type_flags2: 0,
                loot_id: 0,
                pickpocket_loot_id: 0,
                skin_loot_id: 0,
                gold_min: 0,
                gold_max: 0,
                static_flags: [0; 8],
            }],
            |_| 1.0,
        ),
    ));
    session.set_creature_base_stats_store_like_cpp(Arc::new(
        wow_data::CreatureBaseStatsStoreLikeCpp::from_records([
            (
                5,
                2,
                wow_data::CreatureBaseStatsRecordLikeCpp {
                    base_health: [100, 100, 100],
                    base_mana: 600,
                    base_armor: 0,
                    attack_power: 0,
                    ranged_attack_power: 0,
                    base_damage: [0.0; 3],
                },
            ),
            (
                5,
                3,
                wow_data::CreatureBaseStatsRecordLikeCpp {
                    base_health: [100, 100, 100],
                    base_mana: 600,
                    base_armor: 0,
                    attack_power: 0,
                    ranged_attack_power: 0,
                    base_damage: [0.0; 3],
                },
            ),
        ]),
    ));
    session.set_chr_classes_store(Arc::new(ChrClassesStore::from_entries([
        wow_data::character_progression::ChrClassesEntry {
            id: 2,
            display_power: PowerType::Mana as u8,
            ..Default::default()
        },
        wow_data::character_progression::ChrClassesEntry {
            id: 3,
            display_power: PowerType::Focus as u8,
            ..Default::default()
        },
    ])));
    session.set_power_type_store(Arc::new(PowerTypeStore::from_entries([
        wow_data::character_progression::PowerTypeEntry {
            id: 800,
            name_global_string_tag: String::new(),
            cost_global_string_tag: String::new(),
            power_type_enum: PowerType::Mana as i8,
            min_power: 0,
            max_base_power: 0,
            center_power: 0,
            default_power: 0,
            display_modifier: 1,
            regen_interrupt_time_ms: 0,
            regen_peace: 0.0,
            regen_combat: 0.0,
            flags: 0x0080,
        },
        wow_data::character_progression::PowerTypeEntry {
            id: 802,
            name_global_string_tag: String::new(),
            cost_global_string_tag: String::new(),
            power_type_enum: PowerType::Focus as i8,
            min_power: 0,
            max_base_power: 100,
            center_power: 0,
            default_power: 25,
            display_modifier: 1,
            regen_interrupt_time_ms: 0,
            regen_peace: 0.0,
            regen_combat: 0.0,
            flags: 0x0020 | 0x0080,
        },
    ])));

    let full = session.creature_create_stats_like_cpp(90_021, 5, 2, 0, true, 42, 77);
    assert_eq!(
        full.power, 600,
        "C++ SetFullPower(POWER_MANA) uses max/base mana when _regenerateHealth is true"
    );

    let from_spawn = session.creature_create_stats_like_cpp(90_021, 5, 2, 0, false, 42, 77);
    assert_eq!(
        from_spawn.power, 77,
        "C++ SetSpawnHealth copies CreatureData::curmana when _regenerateHealth is false"
    );
    assert_eq!(from_spawn.base_mana, 600);

    let focus = session.creature_create_stats_like_cpp(90_021, 5, 3, 0, false, 42, 77);
    assert_eq!(focus.power_type, PowerType::Focus);
    assert_eq!(focus.max_power, 100);
    assert_eq!(
        focus.power, 25,
        "C++ SetSpawnHealth writes curmana through POWER_MANA and leaves Focus at DB2 DefaultPower"
    );
}

