#[test]
fn character_talent_load_filters_invalid_rows_like_cpp() {
    let (mut session, _, _) = make_session();
    session.set_talent_store(Arc::new(wow_data::TalentStore::from_entries([
        test_talent_entry_like_cpp(101, 2, 50_101),
        test_talent_entry_like_cpp(102, 0, 0),
        test_talent_entry_like_cpp(103, 0, 50_103),
    ])));
    let mut spell_store = wow_data::SpellStore::new();
    spell_store.insert(50_101, test_spell_info_like_cpp(50_101));
    session.set_spell_store(Arc::new(spell_store));
    install_test_talent_tab_store_like_cpp(&mut session);

    assert!(session.load_represented_talent_row_like_cpp(101, 2, 0));
    assert!(!session.load_represented_talent_row_like_cpp(999, 0, 0));
    assert!(!session.load_represented_talent_row_like_cpp(101, 9, 0));
    assert!(!session.load_represented_talent_row_like_cpp(101, 2, 4));
    assert!(!session.load_represented_talent_row_like_cpp(102, 0, 0));
    assert!(!session.load_represented_talent_row_like_cpp(103, 0, 0));

    let packet = session.represented_update_talent_data_packet_like_cpp();
    assert_eq!(
        packet.groups[0].talents,
        vec![wow_packet::packets::misc::TalentInfoLikeCpp {
            talent_id: 101,
            rank: 2,
        }]
    );
}

#[test]
fn character_talent_load_applies_active_spell_side_effects_like_cpp() {
    let (mut session, _, _) = make_session();
    let mut talent = test_talent_entry_like_cpp(406, 0, 14_908);
    talent.spell_id = 14_908;
    talent.overrides_spell_id = 50_000;
    session.set_talent_store(Arc::new(wow_data::TalentStore::from_entries([talent])));

    let mut spell_store = wow_data::SpellStore::new();
    spell_store.insert(
        14_908,
        wow_data::SpellInfo {
            effects: vec![wow_data::SpellEffectInfo {
                effect: wow_data::spell::spell_effect_types::SPELL_EFFECT_LEARN_SPELL,
                effect_trigger_spell: 60_100,
                ..Default::default()
            }],
            ..test_spell_info_like_cpp(14_908)
        },
    );
    spell_store.insert(60_100, test_spell_info_like_cpp(60_100));
    session.set_spell_store(Arc::new(spell_store));
    install_test_talent_tab_store_like_cpp(&mut session);

    let mut known_spells = vec![14_914];
    let mut dependent_spells = HashSet::new();
    assert!(
        session.load_represented_talent_row_with_spell_side_effects_like_cpp(
            406,
            0,
            0,
            &mut known_spells,
            &mut dependent_spells,
        ),
        "C++ _LoadTalents calls AddTalent before _LoadSpells"
    );
    assert!(known_spells.contains(&14_908));
    assert!(known_spells.contains(&60_100));
    assert_eq!(dependent_spells, HashSet::from([14_908, 60_100]));
    assert!(
        session
            .represented_override_spells_like_cpp()
            .get(&50_000)
            .is_some_and(|spells| spells.contains(&14_908))
    );
}

