#[test]
fn cuf_profile_loader_rejects_cpp_oob_id_bug() {
    let (mut session, _, _) = make_session();
    session.clear_represented_cuf_profiles_like_cpp();

    assert!(!session.load_represented_cuf_profile_like_cpp(
        wow_packet::packets::misc::MAX_CUF_PROFILES_LIKE_CPP as u8,
        cuf_profile_for_save_test("Invalid", 99)
    ));
    assert!(
        session
            .represented_load_cuf_profiles_packet_like_cpp()
            .profiles
            .is_empty(),
        "C++ checks id > MAX_CUF_PROFILES before indexing an array of MAX_CUF_PROFILES; Rust rejects id == MAX to avoid the legacy OOB bug"
    );
}

#[test]
fn player_attack_waits_for_active_mover_visibility_flag_like_cpp() {
    let (mut session, _, _) = make_session();
    let canonical = shared_canonical_map_manager();
    let attacker = ObjectGuid::create_player(1, 55);
    let victim = ObjectGuid::create_player(1, 56);

    canonical.lock().unwrap().create_world_map(571, 0);
    session.set_canonical_map_manager(Arc::clone(&canonical));
    session.set_map_store(Arc::new(wow_data::MapStore::from_entries([
        wow_data::MapEntry {
            id: 571,
            instance_type: wow_data::map::MAP_COMMON,
            expansion_id: 0,
            parent_map_id: -1,
            cosmetic_parent_map_id: -1,
            flags1: 0,
            flags2: 0,
        },
    ])));
    session.attach_player_controller_like_cpp(SessionPlayerController::new(
        attacker,
        "Warrior".to_string(),
        Position::new(10.0, 20.0, 30.0, 0.0),
        571,
        1,
        1,
        80,
        0,
    ));
    let _ = session.ensure_canonical_world_map_for_current_player_like_cpp();

    let mut victim_player = Player::new(Some(8), false);
    victim_player
        .unit_mut()
        .world_mut()
        .object_mut()
        .create(victim);
    victim_player
        .unit_mut()
        .world_mut()
        .set_map(571, 0)
        .unwrap();
    victim_player
        .unit_mut()
        .world_mut()
        .relocate(Position::new(11.0, 20.0, 30.0, 0.0));
    victim_player
        .unit_mut()
        .world_mut()
        .object_mut()
        .add_to_world();
    victim_player
        .unit_mut()
        .set_pvp_flag_like_cpp(UnitPvpFlags::PVP);
    canonical
        .lock()
        .unwrap()
        .find_map_mut(571, 0)
        .unwrap()
        .map_mut()
        .insert_map_object_record(wow_entities::MapObjectRecord::new_player(victim_player).unwrap())
        .unwrap();

    session.set_active_player_local_flags_like_cpp(0);
    assert_eq!(
        session.start_player_attack_like_cpp(victim),
        PlayerAttackStartLikeCppResult::Rejected
    );
    assert_eq!(session.combat_target, None);

    session.apply_move_init_active_mover_complete_like_cpp(0);
    assert_eq!(
        session.start_player_attack_like_cpp(victim),
        PlayerAttackStartLikeCppResult::Accepted {
            send_attack_start: true
        }
    );
}

