#[tokio::test]
async fn gameobject_use_spellcaster_casts_and_ticks_charges_like_cpp() {
    let (mut session, _pkt_tx, _send_rx) = make_session();
    let player_guid = ObjectGuid::create_player(1, 99);
    let gameobject_guid =
        ObjectGuid::create_world_object(HighGuid::GameObject, 0, 1, 571, 0, 777, 20);

    session.set_state(SessionState::LoggedIn);
    assert!(session.use_represented_gameobject_spellcaster_like_cpp(
        gameobject_guid,
        player_guid,
        777,
        wow_entities::SpellcasterUseSource {
            spell_id: 3456,
            charges: 1,
            party_only: false,
        },
    ));
    assert_eq!(
        session.represented_gameobject_use_effects,
        vec![
            RepresentedGameObjectUseEffect::RemoveMountedAuras {
                gameobject_guid,
                player_guid,
            },
            RepresentedGameObjectUseEffect::GameObjectUseCountIncremented {
                gameobject_guid,
                use_count: 1,
            },
            RepresentedGameObjectUseEffect::OutdoorPvpCustomSpellRequested {
                gameobject_guid,
                player_guid,
                gameobject_entry: 777,
                spell_id: 3456,
                go_type: wow_entities::GAMEOBJECT_TYPE_SPELLCASTER,
                spell_lookup_difficulty_id: 0,
                spell_info_missing: false,
            },
            RepresentedGameObjectUseEffect::GameObjectPostUseSpellCast {
                gameobject_guid,
                target_guid: player_guid,
                caster_guid: player_guid,
                spell_id: 3456,
                triggered: false,
                caster: RepresentedGameObjectSpellCaster::User,
                spell_lookup_difficulty_id: 0,
            },
        ]
    );
    assert_eq!(
        session
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .unwrap()
            .use_count,
        1
    );
    assert_eq!(
        session
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .unwrap()
            .max_charges,
        Some(1)
    );
    session.represented_gameobject_use_effects.clear();

    session.process_pending().await;

    assert_eq!(
        session.represented_gameobject_use_effects,
        vec![RepresentedGameObjectUseEffect::GameObjectChargesDepleted {
            gameobject_guid,
            max_charges: 1,
            loot_state: wow_entities::LootState::JustDeactivated,
        }]
    );
    assert_eq!(
        session
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .unwrap()
            .use_count,
        0
    );
    assert_eq!(
        session
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .unwrap()
            .loot_state,
        Some(wow_entities::LootState::JustDeactivated)
    );
}

#[tokio::test]
async fn process_pending_ticks_guardpost_charges_like_cpp_get_charges() {
    let (mut session, _pkt_tx, _send_rx) = make_session();
    session.set_state(SessionState::LoggedIn);
    let gameobject_guid =
        ObjectGuid::create_world_object(HighGuid::GameObject, 0, 1, 571, 0, 777, 212);
    {
        let state = session
            .represented_gameobject_use_states
            .entry(gameobject_guid)
            .or_default();
        state.go_type = Some(wow_entities::GAMEOBJECT_TYPE_GUARDPOST as u8);
        state.use_count = 2;
        state.max_charges = Some(2);
    }

    session.process_pending().await;

    let state = session
        .represented_gameobject_use_states
        .get(&gameobject_guid)
        .unwrap();
    assert_eq!(state.use_count, 0);
    assert_eq!(
        state.loot_state,
        Some(wow_entities::LootState::JustDeactivated)
    );
    assert_eq!(
        session.represented_gameobject_use_effects,
        vec![RepresentedGameObjectUseEffect::GameObjectChargesDepleted {
            gameobject_guid,
            max_charges: 2,
            loot_state: wow_entities::LootState::JustDeactivated,
        }]
    );
}

